contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function
    function run(address candidate) public payable {
        // record owner before calling
        address beforeOwner = c.owner(); if (__ESBMC_reverted()) return;

        bool reverted;
        bool returnedTrue = false;
        bool ok = c.setOwner(candidate); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
            returnedTrue = ok;
        }

        address afterOwner = c.owner(); if (__ESBMC_reverted()) return;

        // General rule:
        // If the call did not revert and returned true, then owner must equal candidate.
        // If the call reverted, owner must remain as before.
        assert((reverted == false && returnedTrue == true && afterOwner == candidate) ||
               (reverted == true && afterOwner == beforeOwner));
    }

    receive() external payable {}
}

